import os
from pathlib import Path

def resolve_static_asset(root_dir: str, requested_filename: str) -> str:
    """Serve static asset file. VULNERABLE: Direct path join and normpath allow traversal."""
    cleaned = requested_filename.lstrip("/\\")
    full_path = os.path.normpath(os.path.join(root_dir, cleaned))
    with open(full_path, "r", encoding="utf-8") as f:
        return f.read()

def get_asset_info(root_dir: str, requested_filename: str) -> dict:
    return {"root": root_dir, "file": requested_filename}
